head.script:
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).textContent == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 name1 header의 역삼각형모양을 클릭한다.
    //1. After running the sample, click the inverted triangle of the name1 header.
    //Verify step 1. The custom filter screen is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_customFilter').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 찾을조건의 selectbox List data를 확인한다.
    //2. Check the selectbox List data of the search condition.
    //Verify step 2. It is shown as label value (A, B, C)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_item_0_autocomplete_column5_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_item_0_autocomplete_column5_itemTable_0', 'A')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_item_0_autocomplete_column5_itemTable_1', 'B')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_item_0_autocomplete_column5_itemTable_2', 'C')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
